import type { ChoiceOption, ErrorCategory, GuidedExperiment, Lesson, Task, TaskLevel } from './types';
import { CHEM_LESSONS, PHYS_LESSONS } from './semester1';
import { BIO_LESSONS, HISTO_LESSONS, TERM_LESSONS } from './bio1';

// Aufgaben für die Fächer des 1. Studienjahres. Jedes Lernziel der neuen Lektionen hat mindestens eine Aufgabe.

const S = 'zu_pruefen' as const;
const ALL: Lesson[] = [...CHEM_LESSONS, ...PHYS_LESSONS, ...BIO_LESSONS, ...HISTO_LESSONS, ...TERM_LESSONS];
/** Lernziel Nr. i (0-basiert) einer Lektion – so bleiben Aufgabe und Lektion sicher synchron. */
function O(lesson: string, i: number): string {
  const l = ALL.find((x) => x.id === lesson);
  if (!l || !l.objectives[i]) throw new Error(`Lernziel ${lesson}[${i}] fehlt`);
  return l.objectives[i];
}
const src = (id: string, locator?: string) => [{ id, ...(locator ? { locator } : {}) }];

function sc(id: string, lesson: string, oi: number, level: TaskLevel, category: ErrorCategory, source: string, prompt: string, correct: string, wrong: [string, string, ErrorCategory?][], explanation: string): Task {
  const opts: ChoiceOption[] = [{ id: 'a', text: correct }, ...wrong.map(([text, why, cat], i) => ({ id: String.fromCharCode(98 + i), text, why, category: cat ?? category }))];
  const rot = id.length % opts.length;
  const options = [...opts.slice(rot), ...opts.slice(0, rot)];
  return { id, type: 'single', prompt, level, lessons: [lesson], objective: O(lesson, oi), category, sources: src(source), status: S, options, correct: 'a', explanation };
}
function fx(id: string, lesson: string, oi: number, source: string, prompt: string, givens: string, answer: number, tolerance: number, unit: string, solution: string, explanation: string, level: TaskLevel = 'anwendung'): Task {
  return { id, type: 'formula', level, lessons: [lesson], objective: O(lesson, oi), category: 'formel', sources: src(source), status: S, prompt, givens, answer, tolerance, unit, solution, explanation };
}
function mt(id: string, lesson: string, oi: number, source: string, prompt: string, pairs: [string, string][], explanation: string, level: TaskLevel = 'verstaendnis', category: ErrorCategory = 'begriff'): Task {
  return { id, type: 'match', level, lessons: [lesson], objective: O(lesson, oi), category, sources: src(source), status: S, prompt, pairs: pairs.map(([left, right]) => ({ left, right })), explanation };
}
function od(id: string, lesson: string, oi: number, source: string, prompt: string, items: string[], explanation: string): Task {
  return { id, type: 'order', level: 'wissen', lessons: [lesson], objective: O(lesson, oi), category: 'reihenfolge', sources: src(source), status: S, prompt, items, explanation };
}

